def make_node(val, pos, color=BLUE):
    c = Circle(radius=0.4, color=color, fill_opacity=0.8).move_to(pos)
    t = Text(str(val), font_size=24, color=WHITE).move_to(pos)
    return VGroup(c, t)

def make_array(values):
    cells = VGroup(*[
        VGroup(Square(side_length=0.8, color=BLUE, fill_opacity=0.3), Text(str(v), font_size=22))
        for v in values
    ]).arrange(RIGHT, buff=0.1).move_to(ORIGIN)
    for c in cells:
        c[1].move_to(c[0].get_center())
    if cells.width > 11.0:
        cells.scale_to_fit_width(11.0)
    return cells
